/**
 * Register the TTOken Code composer chips into `conversation.input.left`: the
 * working folder, then the Git branch read from the checkout's HEAD file.
 * Generated by ttoken/apply-brand.mjs from ttoken/client/composer/install.ts; edit it there.
 */
import type { Context } from '@deepseek-ai/cordis'
import type {} from '@deepseek-ai/dsh-api-remotes/client'
import type { SessionId } from '@deepseek-ai/dsh-session/types'
import { BranchChip, FolderChip, type BranchChipInjected, type GitHead } from './TtokenChips.tsx'
import { TTOKEN_COMPOSER_NS, de, en, es, fr, ja, pt, ru, zh } from './locales.ts'

/** `.git/HEAD` naming a branch. */
const HEAD_REF = /^ref: refs\/heads\/(.+)$/
/** `.git/HEAD` holding a commit (detached HEAD). */
const HEAD_COMMIT = /^[0-9a-f]{7,64}$/
/** A linked worktree's `.git` file pointing at its Git directory. */
const GIT_DIR = /^gitdir: (.+)$/

/**
 * Install the chips and their copy for the plugin lifetime.
 * @param ctx - the Conversation plugin context (slots and locale).
 */
export function installTtokenComposer(ctx: Context): void {
  ctx.effect(() => ctx.locale.register(TTOKEN_COMPOSER_NS, { zh, en, ja, es, fr, de, ru, pt }), 'ttoken composer: dictionaries')
  ctx.slots.inject('conversation.input.left', () => ctx.slots.register({
    name: 'conversation.input.left', id: 'ttoken-folder', order: 10, locale: TTOKEN_COMPOSER_NS,
  }, FolderChip))
  ctx.inject(['remote', 'remote.workspaceFiles'], (scope: Context) => {
    const readLine = async (sessionId: SessionId, path: string, signal: AbortSignal): Promise<string | null> => {
      const result = await scope.remote.workspaceFiles.read(sessionId, path, { limit: 1 }, signal)
      return result.ok ? result.value.text.trim() : null
    }
    const readHead = async (sessionId: SessionId, signal: AbortSignal): Promise<GitHead | null> => {
      let head = await readLine(sessionId, '.git/HEAD', signal)
      if (head === null) {
        const pointer = await readLine(sessionId, '.git', signal)
        const gitDir = pointer === null ? undefined : GIT_DIR.exec(pointer)?.[1]
        if (gitDir === undefined) return null
        head = await readLine(sessionId, `${gitDir}/HEAD`, signal)
        if (head === null) return null
      }
      const branch = HEAD_REF.exec(head)?.[1]
      if (branch !== undefined) return { kind: 'branch', name: branch }
      return HEAD_COMMIT.test(head) ? { kind: 'detached', commit: head.slice(0, 7) } : null
    }
    scope.slots.inject('conversation.input.left', () => scope.slots.register({
      name: 'conversation.input.left', id: 'ttoken-branch', order: 20, locale: TTOKEN_COMPOSER_NS,
      inject: (sessionId: SessionId): BranchChipInjected => ({ readHead: signal => readHead(sessionId, signal) }),
    }, BranchChip))
  })
}
